    while pos<len(data):
        ln=struct.unpack('>I',data[pos:pos+4])[0]; typ=data[pos+4:pos+8]; chunk=data[pos+8:pos+8+ln]
        if typ==b'IHDR': w,h,bd,ct=struct.unpack('>IIBB',chunk[:10])
        elif typ==b'IDAT': idat+=chunk
        elif typ==b'IEND': break
        pos+=12+ln
    raw=zlib.decompress(idat); bpp={0:1,2:3,3:1,4:2,6:4}[ct]*(bd//8); stride=w*bpp
    out=bytearray(h*stride); prev=bytearray(stride); p=0
    for y in range(h):
        f=raw[p]; p+=1; line=bytearray(raw[p:p+stride]); p+=stride
        if f==1:
            for i in range(bpp,stride): line[i]=(line[i]+line[i-bpp])&0xFF
        elif f==2:
            for i in range(stride): line[i]=(line[i]+prev[i])&0xFF
        elif f==3:
            for i in range(stride):
                a=line[i-bpp] if i>=bpp else 0
                line[i]=(line[i]+((a+prev[i])>>1))&0xFF
        elif f==4:
            for i in range(stride):
                a=line[i-bpp] if i>=bpp else 0; b=prev[i]; c=prev[i-bpp] if i>=bpp else 0
                pa,pb,pc=abs(b-c),abs(a-c),abs(a+b-2*c)
                pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                line[i]=(line[i]+pr)&0xFF
        out[y*stride:(y+1)*stride]=line; prev=line
    return w,h,bpp,bytes(out)
w,h,bpp,px=read_png('/tmp/dash-b.png')
def get(x,y):
    o=(y*w+x)*bpp; return px[o],px[o+1],px[o+2]

