// 一次性探针（不属于仓库）：验证 legacy 标记确实改变渲染，且方向正确。
//
// 判据只在**绘图区内部**统计（x∈[50,w-20], y∈[35,h-30]），
// 以避开 Y 轴刻度文字的抗锯齿灰（0x88 混白后可能恰好等于 0x9E）。
//
// 同进程对比两种输入，唯一差别是中间点的 legacy 标志：
//   非 legacy → 中间列应有绿色连线，绘图区内不应有灰色标记
//   legacy    → 中间列不应有绿色连线，绘图区内应有灰色空心标记
#include <QApplication>
#include <QImage>
#include <QPainter>
#include <cstdio>

#include "ui/line_chart_widget.hpp"

using namespace weaknet::dashboard;

struct Counts { int green_plot; int green_mid; int grey_plot; };

static Counts render(bool legacy_mid) {
    HistorySeries series;
    series.points.push_back(HistoryPoint{"t0", 20.0, false});
    series.points.push_back(HistoryPoint{"t1", 50.0, legacy_mid});
    series.points.push_back(HistoryPoint{"t2", 80.0, false});

    LineChartWidget chart;
    chart.setSeries(series);

    QImage img(400, 200, QImage::Format_RGB32);
    img.fill(Qt::white);
    {
        QPainter p(&img);
        p.setRenderHint(QPainter::Antialiasing, true);
        chart.paint(&p, img.rect());
    }

    const QRgb green = qRgb(0x2E, 0x7D, 0x32);
    const QRgb grey  = qRgb(0x9E, 0x9E, 0x9E);
    const int midx = img.width() / 2;

    Counts c{0, 0, 0};
    for (int y = 35; y < img.height() - 30; ++y) {
        for (int x = 50; x < img.width() - 20; ++x) {
            const QRgb p = img.pixel(x, y);
            if (p == green) {
                ++c.green_plot;
                if (x == midx) ++c.green_mid;
            } else if (p == grey) {
                ++c.grey_plot;
            }
        }
    }
    return c;
}

int main(int argc, char** argv) {
    qputenv("QT_QPA_PLATFORM", "offscreen");
    QApplication app(argc, argv);

    const Counts v2  = render(false);
    const Counts leg = render(true);

    std::printf("non-legacy: green_plot=%d green_mid=%d grey_plot=%d\n",
                v2.green_plot, v2.green_mid, v2.grey_plot);
    std::printf("legacy    : green_plot=%d green_mid=%d grey_plot=%d\n",
                leg.green_plot, leg.green_mid, leg.grey_plot);

    const bool ok = (v2.green_mid > 0) && (v2.grey_plot == 0) &&
                    (leg.green_mid == 0) && (leg.grey_plot > 0) &&
                    (leg.green_plot < v2.green_plot);
    std::printf("PROBE %s\n", ok ? "PASS" : "FAIL");
    return ok ? 0 : 1;
}
