    bool initConnection() {
        DBusError err;
        dbus_error_init(&err);
        // 连接到 D-Bus 系统总线（与服务端一致）
        conn_ = dbus_bus_get(DBUS_BUS_SYSTEM, &err);
        if (dbus_error_is_set(&err)) {
            LOG_ERROR(LogModule::CLIENT, "连接DBus总线失败: " << err.message);
            dbus_error_free(&err);
        }
        connected_ = (conn_ != nullptr);
        return connected_;
    }

