#include <QByteArray>
#include <QCommandLineParser>
#include <QPixmap>
#include <QTimer>

#include <cstdlib>

#include "ui/main_window.hpp"

/**
 * @brief 未显式指定平台插件时，默认用 eglfs
 *
 * 头注释推荐了 `eglfs`，但在此之前代码里没有设置任何默认值：完全依赖
 * `QT_QPA_PLATFORM` 环境变量，未设置时由 Qt 在可用插件里自行挑选，板端
 * 挑到哪个不确定。这里把推荐落到实处。
 *
 * 三条约束：
 *
 * 1. **只在未指定时生效**：`-platform` 命令行参数与 `QT_QPA_PLATFORM`
 *    环境变量都优先。`-platform` 必须在 QApplication 构造前由 qputenv 之外
 *    的路径生效，所以这里判断环境变量是否已设置即可——Qt 的 `-platform`
 *    会覆盖 qputenv 设置的值。
 * 2. **用 qputenv 而不是 setenv**：Qt 缓存平台插件名，`qputenv` 会在
 *    QGuiApplication 初始化前同步更新，行为一致且有明确文档保证。
 * 3. **测试与截图路径不受影响**：`--screenshot` 的调用方本来就显式设了
 *    `QT_QPA_PLATFORM=offscreen`，属于"已指定"，不会被这里覆盖。
 */
static void apply_default_platform() {
    if (!qEnvironmentVariableIsEmpty("QT_QPA_PLATFORM")) {
        return;  // 调用方已显式指定（命令行 -platform 或环境变量）
    }
    qputenv("QT_QPA_PLATFORM", QByteArrayLiteral("eglfs"));
}

int main(int argc, char* argv[]) {
    apply_default_platform();
    QApplication app(argc, argv);

