229	    // 诊断的人读摘要（diagnosis 独占）：服务端给的是完整句子，
230	    // 比 primary_issue 这类机器 token 更适合直接展示给用户
231	    summary_template_label_ = new QLabel;
232	    summary_template_label_->setWordWrap(true);
233	    summary_template_label_->hide();
234	    root->addWidget(summary_template_label_);
235	
236	    // 次要问题 / 已排除原因 / 证据（diagnosis 独占，默认折叠）
237	    diagnosis_extra_label_ = new QLabel;
238	    diagnosis_extra_label_->setWordWrap(true);
239	    diagnosis_extra_label_->setStyleSheet(QStringLiteral("color: #666666;"));
240	    diagnosis_extra_label_->hide();
241	    root->addWidget(diagnosis_extra_label_);
242	
243	    setCentralWidget(central);
244	
245	    status_bar_label_ = new QLabel(QStringLiteral("就绪"));
246	    statusBar()->addWidget(status_bar_label_);
247	}
