276	void MainWindow::apply_diagnosis(const DiagnosisSnapshot& snap) {
277	    if (!snap.valid) {
278	        diagnosis_label_->setText(QStringLiteral("诊断：数据无效"));
279	        summary_template_label_->hide();
280	        diagnosis_extra_label_->hide();
281	        return;
282	    }
283	
284	    // 第一行：机器可判定的结论（故障域 + 置信度）
285	    // 注意 fault_domain == "NONE" 表示服务端明确判定「无需排查」
286	    // （见 diagnosis_engine.hpp:135 的 all_metrics_healthy 分支），
287	    // 不是「不知道」，所以照样展示，但把置信度放前面更醒目。
288	    QString text = QStringLiteral("诊断：故障域 %1 · 置信度 %2")
289	                       .arg(QString::fromStdString(snap.fault_domain),
290	                            QString::fromStdString(snap.confidence));
291	
292	    if (!snap.actions.empty()) {
293	        // 动作只提示数量与最优先级别，不展示 action_id：
294	        // 看板不执行任何动作，真正执行必须走 weaknet_execute_action() 且需 root。
295	        int top_priority = snap.actions.front().priority;
296	        for (const ActionSuggestion& action : snap.actions) {
297	            top_priority = std::min(top_priority, action.priority);
298	        }
299	        text += QStringLiteral(" · 建议动作 %1 项（最高优先级 %2）")
300	                    .arg(static_cast<int>(snap.actions.size()))
301	                    .arg(top_priority);
302	    }
303	    diagnosis_label_->setText(text);
304	
305	    // 第二行：人读摘要。default_summary_template 是完整句子，
306	    // 比 primary_issue 这类机器 token 更适合直接呈现给用户。
307	    //
308	    // primary_issue 作为兜底：服务端若没给 default_summary_template，
309	    // 这里就只剩 primary_issue 可选。丢掉它会让整行隐藏，而"没有摘要"
310	    // 和"没有诊断结论"在界面上是同一个样子，信息就白解析了。
311	    if (!snap.summary_template.empty()) {
312	        summary_template_label_->setText(
313	            QString::fromStdString(snap.summary_template));
314	        summary_template_label_->show();
315	    } else if (!snap.primary_issue.empty()) {
316	        // 加前缀标明这是机器标识而非完整句子，避免被当成结论直接引用
317	        summary_template_label_->setText(
318	            QStringLiteral("首要问题 %1")
319	                .arg(QString::fromStdString(snap.primary_issue)));
320	        summary_template_label_->show();
321	    } else {
322	        summary_template_label_->hide();
323	    }
324	
325	    // 第三行：次要问题 / 已排除原因 / 证据 ID。
326	    // 默认折叠成一行灰色小字；证据 ID（形如 ev_radxa_..._s101_01）是机器标识，
327	    // 铺在界面上纯噪声，放进 tooltip 让需要排查的人能查到即可。
328	    QStringList extra;
329	    QStringList evidence_tooltip;
330	    if (!snap.secondary_issues.empty()) {
331	        QStringList items;
332	        for (const std::string& issue : snap.secondary_issues) {
333	            items.append(QString::fromStdString(issue));
334	        }
335	        extra.append(QStringLiteral("次要问题 %1 项").arg(items.size()));
336	        evidence_tooltip.append(QStringLiteral("次要问题：") +
337	                                items.join(QStringLiteral("、")));
338	    }
339	    if (!snap.excluded_causes.empty()) {
340	        QStringList items;
341	        for (const ExcludedCause& cause : snap.excluded_causes) {
342	            items.append(QStringLiteral("%1（%2）")
343	                             .arg(QString::fromStdString(cause.cause),
344	                                  QString::fromStdString(cause.reason)));
345	        }
346	        extra.append(QStringLiteral("已排除 %1 项").arg(items.size()));
347	        evidence_tooltip.append(QStringLiteral("已排除原因：") +
348	                                items.join(QStringLiteral("、")));
349	    }
350	    if (!snap.evidence_refs.empty()) {
351	        QStringList items;
352	        for (const std::string& ref : snap.evidence_refs) {
353	            items.append(QString::fromStdString(ref));
354	        }
355	        extra.append(QStringLiteral("证据 %1 条").arg(items.size()));
356	        evidence_tooltip.append(QStringLiteral("证据 ID：") +
357	                                items.join(QStringLiteral("\n")));
358	    }
359	
360	    if (extra.isEmpty()) {
361	        diagnosis_extra_label_->hide();
362	        diagnosis_extra_label_->setToolTip(QString());
363	    } else {
364	        diagnosis_extra_label_->setText(extra.join(QStringLiteral("　")));
365	        diagnosis_extra_label_->setToolTip(evidence_tooltip.join(QStringLiteral("\n")));
366	        diagnosis_extra_label_->show();
367	    }
368	}
