384	void MainWindow::onRefreshFinished() {
385	    refresh_in_flight_ = false;
386	    // 按轮复位：本轮全部成功才回到「就绪」。
387	    // 之前用「状态栏文字是否以『取数失败』开头」判断，那是跨轮持久状态——
388	    // 只要历史上失败过一次，后面每轮成功也永远停在失败文案上。
389	    if (!round_had_failure_) {
390	        status_bar_label_->setText(QStringLiteral("就绪"));
391	    }
392	    round_had_failure_ = false;
393	}
