396	// 渲染
397	// ---------------------------------------------------------------------------
398	
399	void MainWindow::apply_experience(const ExperienceSnapshot& snap) {
400	    timestamp_label_->setText(
401	        QDateTime::currentDateTime().toString(QStringLiteral("yyyy-MM-dd HH:mm:ss")));
402	
403	    if (!snap.available()) {
404	        // 服务端明确说明「还没有评估」或「快照过期」——如实展示，不显示 0 分
405	        iface_label_->setText(QString::fromStdString(snap.interface_name));
406	        score_label_->setText(QStringLiteral("--"));
407	        score_label_->setStyleSheet(QString());
408	        summary_label_->clear();
409	        profile_label_->setText(QStringLiteral("--"));
410	        experience_detail_label_->hide();
411	        // 不清空 summary_template_label_ / diagnosis_extra_label_ / diagnosis_label_：
412	        // 它们归 diagnosis 所有，experience 无权处置。反过来也一样，
413	        // 这样任一侧晚到或失败都不会抹掉另一侧已经显示的内容。
414	        experience_label_->setText(
415	            QStringLiteral("体验：等待评估（%1）")
416	                .arg(QString::fromStdString(snap.unavailable_reason)));
417	        return;
418	    }
419	
420	    iface_label_->setText(QString::fromStdString(snap.interface_name));
421	    score_label_->setText(QString::number(snap.display_score, 'f', 1));
422	
423	    // 整体分数按状态着色
424	    const QString color = state_color(QString::fromStdString(snap.overall_state));
425	    score_label_->setStyleSheet(QStringLiteral("color: %1;").arg(color));
426	
427	    // 评估档位：同一维度在不同 profile 下的判定阈值不同，必须标出来
428	    profile_label_->setText(QStringLiteral("档位 %1 / 覆盖 %2")
429	                                .arg(QString::fromStdString(snap.assessment_profile),
430	                                     QString::fromStdString(snap.overall_coverage)));
431	
432	    // 各维度状态汇总：一眼看出有几个 BAD / DEGRADED，不必逐行扫
433	    int healthy = 0;
434	    int degraded = 0;
435	    int failed = 0;
436	    int unknown = 0;
437	    snap.count_by_state(&healthy, &degraded, &failed, &unknown);
438	    summary_label_->setText(
439	        QStringLiteral("<span style=\"color:#2E7D32\">● %1</span> "
440	                       "<span style=\"color:#F9A825\">● %2</span> "
441	                       "<span style=\"color:#C62828\">● %3</span> "
442	                       "<span style=\"color:#9E9E9E\">● %4</span>")
443	            .arg(healthy)
444	            .arg(degraded)
445	            .arg(failed)
446	            .arg(unknown));
447	
448	    // 服务端给出的警告直接展示：这是它主动标记的异常，不该被界面吞掉
449	    if (!snap.warnings.empty()) {
450	        QStringList parts;
451	        parts.reserve(static_cast<int>(snap.warnings.size()));
452	        for (const std::string& warning : snap.warnings) {
453	            parts.append(QString::fromStdString(warning));
454	        }
455	        experience_detail_label_->setText(
456	            QStringLiteral("⚠ %1").arg(parts.join(QStringLiteral(" · "))));
457	        experience_detail_label_->show();
458	    } else {
459	        experience_detail_label_->hide();
460	    }
461	
462	    // 首要问题并入结论行：experience_label_ 此时已被本函数独占写入，
463	    // 不会再被 diagnosis 侧覆盖，所以不需要第二个标签。
464	    QString text = QStringLiteral("体验：%1")
465	                       .arg(QString::fromStdString(snap.overall_state));
466	    if (!snap.primary_issue.empty()) {
467	        text += QStringLiteral(" · 首要问题 %1")
468	                    .arg(QString::fromStdString(snap.primary_issue));
469	    }
470	    experience_label_->setText(text);
471	
472	    update_status_label(snap.ip_reachability, ip_reachability_label_);
473	    update_status_label(snap.responsiveness, responsiveness_label_);
474	    update_status_label(snap.reliability, reliability_label_);
475	    update_status_label(snap.rf_health, rf_health_label_);
476	
477	    update_status_label(snap.dns_service, dns_label_);
478	    update_status_label(snap.tcp_connect, tcp_connect_label_);
479	    update_status_label(snap.tcp_rtt, tcp_rtt_label_);
480	    update_status_label(snap.http_access, http_access_label_);
481	    update_status_label(snap.captive_portal, captive_portal_label_);
482	    update_status_label(snap.active_dns, active_dns_label_);
483	    update_status_label(snap.active_tcp, active_tcp_label_);
484	    update_status_label(snap.active_https, active_https_label_);
485	    update_status_label(snap.active_portal, active_portal_label_);
486	}
487	
488	void MainWindow::update_status_label(const SleItem& item, QLabel* state_label) {
489	    if (!state_label) {
490	        return;
491	    }
492	
493	    // reason 是服务端给出的人可读 token（如 jitter_excessive、no_dns_observations），
494	    // 它解释了「为什么是这个状态」。用 tooltip 挂在标签上，不占版面但可查。
495	    const QString reason = QString::fromStdString(item.reason);
496	    state_label->setToolTip(reason.isEmpty()
497	                                ? QString()
498	                                : QStringLiteral("%1：%2")
499	                                      .arg(QString::fromStdString(item.key), reason));
500	
501	    // 不适用的维度（如有线链路下的 RF 健康）显式标注，不显示 GOOD/BAD
502	    if (!item.applicable()) {
503	        state_label->setText(QStringLiteral("不适用"));
504	        state_label->setStyleSheet(QStringLiteral("color: #9E9E9E;"));
505	        return;
506	    }
507	
508	    if (!item.has_value()) {
509	        state_label->setText(QStringLiteral("未知"));
510	        state_label->setStyleSheet(QStringLiteral("color: #9E9E9E;"));
511	        return;
512	    }
513	
514	    // 部分覆盖的维度加后缀，提示结论置信度较低
515	    QString text = QString::fromStdString(item.state);
516	    if (item.coverage == "PARTIAL") {
517	        text += QStringLiteral(" (部分)");
518	    }
519	    state_label->setText(text);
520	    state_label->setStyleSheet(
521	        QStringLiteral("color: %1;").arg(state_color(QString::fromStdString(item.state))));
522	}
523	
524	QString MainWindow::state_color(const QString& state) {
525	    // 取值依据 server/include/assurance/health_state.hpp:15-23
526	    if (state == QLatin1String("GOOD")) {
527	        return QStringLiteral("#2E7D32");      // 绿
528	    }
529	    if (state == QLatin1String("DEGRADED")) {
530	        return QStringLiteral("#F9A825");      // 黄
531	    }
532	    if (state == QLatin1String("BAD")) {
533	        return QStringLiteral("#C62828");      // 红
534	    }
535	    return QStringLiteral("#9E9E9E");          // 灰（UNKNOWN）
536	}
