57	    explicit MainWindow(QWidget* parent = nullptr);
58	    ~MainWindow() override;
59	
60	    /**
61	     * @brief 启动后台取数与自动刷新
62	     *
63	     * 不从构造函数调用：构造时窗口还没显示，立刻取数会拖慢启动。
