69	     *
70	     * 空字符串表示不限制（服务端按全部网卡返回），标题会写成「全部网卡」。
71	     *
72	     * 必须在 `start()` 之前调用。`main.cpp` **无条件调用**（不传 `-i` 时传空串）：
73	     * 它同时负责设置 `history_limit_` 和标题，跳过调用会让标题与实际查询范围对不上。
74	     */
75	    void setInterface(const QString& interface_name);
76	
77	private slots:
78	    void onExperienceReady(const QByteArray& json);
79	    void onDiagnosisReady(const QByteArray& json);
80	    void onHistoryReady(const QByteArray& json);
81	    void onFetchFailed(const QString& stage, const QString& error);
82	    void onRefreshFinished();
83	    void onRefreshClicked();
