86	    void build_ui();
87	    void apply_experience(const ExperienceSnapshot& snap);
88	    void apply_diagnosis(const DiagnosisSnapshot& snap);
89	    void update_status_label(const SleItem& item, QLabel* state_label);
90	    static QString state_color(const QString& state);
91	
92	    DataFetchThread* fetcher_ = nullptr;
93	    LineChartWidget* chart_ = nullptr;
94	
95	    /// 历史查询使用的网卡（空表示全部）。
96	    ///
97	    /// 这是**请求侧**的事实，不能从 `HistorySeries` 推断：
98	    /// 查询全部网卡时，任意一条记录的 iface 都不代表整个序列。
99	    /// 折线图标题直接用它，避免出现「标题写着 wlan0，实际混了 eth0」。
100	    QString interface_;
101	
102	    // 顶栏
103	    QPushButton* refresh_button_ = nullptr;
104	    QLabel* iface_label_ = nullptr;
105	    QLabel* score_label_ = nullptr;
106	    QLabel* timestamp_label_ = nullptr;
107	
108	    /// 各维度状态汇总「● 3 ● 2 ● 1 ○ 7」（count_by_state 的消费者）
109	    QLabel* summary_label_ = nullptr;
110	    /// 评估档位与覆盖度（assessment_profile 的消费者）
111	    QLabel* profile_label_ = nullptr;
