114	    QLabel* ip_reachability_label_ = nullptr;
115	    QLabel* responsiveness_label_ = nullptr;
116	    QLabel* reliability_label_ = nullptr;
117	    QLabel* rf_health_label_ = nullptr;
118	
119	    QLabel* dns_label_ = nullptr;
120	    QLabel* tcp_connect_label_ = nullptr;
121	    QLabel* tcp_rtt_label_ = nullptr;
122	    QLabel* http_access_label_ = nullptr;
123	    QLabel* captive_portal_label_ = nullptr;
124	    QLabel* active_dns_label_ = nullptr;
125	    QLabel* active_tcp_label_ = nullptr;
126	    QLabel* active_https_label_ = nullptr;
