130	    //
131	    // experience 与 diagnosis 是**两个独立的异步数据源**，返回时序不定
132	    // （DataFetchThread 先发 experienceReady 再发 diagnosisReady，但二者
133	    // 都是队列连接，实际到达顺序不保证）。因此它们各自拥有独立控件：
134	    // 共用一个 QLabel 会让后到者覆盖先到者的内容。
135	    /// 体验快照的结论行：等待评估原因 / 首要问题（experience 独占）
136	    QLabel* experience_label_ = nullptr;
137	    /// 体验快照的警告（experience 独占，无警告时隐藏）
138	    QLabel* experience_detail_label_ = nullptr;
139	    /// 诊断结论行：故障域 + 置信度 + 动作数（diagnosis 独占）
140	    QLabel* diagnosis_label_ = nullptr;
141	    /// 诊断的人读摘要（diagnosis 独占，default_summary_template 的消费者）
142	    QLabel* summary_template_label_ = nullptr;
143	    /// 次要问题 / 已排除原因 / 证据（diagnosis 独占，可折叠）
144	    QLabel* diagnosis_extra_label_ = nullptr;
145	    QLabel* status_bar_label_ = nullptr;
146	
