150	    /// 一旦出现过失败，之后即使每轮都成功也永远不会复位回「就绪」。
151	    /// 这里按轮记录，onRefreshFinished 时消费并清空。
152	    bool round_had_failure_ = false;
153	
154	    bool refresh_in_flight_ = false;
155	};
