#include <QApplication>
#include <QLabel>
#include <QWidget>
#include <QVBoxLayout>
#include <QDebug>

int main(int argc, char** argv) {
    QApplication app(argc, argv);

    QWidget w;
    auto* lay = new QVBoxLayout(&w);
    QLabel* a = new QLabel("global-only");
    QLabel* b = new QLabel("widget-override");
    lay->addWidget(a);
    lay->addWidget(b);

    // 全局：所有 QLabel 应该红色
    qApp->setStyleSheet("QLabel { color: red; font-size: 20px; }");
    // 部件级：只改颜色——能否保留全局的 font-size？
    b->setStyleSheet("color: blue;");

    qDebug() << "a styleSheet:" << a->styleSheet();
    qDebug() << "b styleSheet:" << b->styleSheet();
    qDebug() << "a palette color:" << a->palette().color(QPalette::WindowText).name();
    qDebug() << "b palette color:" << b->palette().color(QPalette::WindowText).name();
    qDebug() << "b font size:" << b->font().pointSizeF();

    // 关键验证：部件级 setStyleSheet 后，全局的 font-size 还有效吗？
    // 用渲染验证不可行，直接读 QStyleSheetStyle 的解析结果不好拿。
    // 改读有效字体（Qt 会把 QSS 的 font-size 反映到 font() 上）
