static int text_height(QWidget* w, int y0, int y1) {
    QImage img(w->size(), QImage::Format_RGB32);
    img.fill(Qt::white);
    QPainter p(&img);
    w->render(&p);
    p.end();
    int top=-1, bottom=-1;
