/**
 * @file theme.cpp
 * @brief 看板视觉主题实现
 */

#include "theme.hpp"

#include <QApplication>
#include <QFont>
#include <QPalette>
#include <QStyleFactory>

namespace weaknet {
namespace dashboard {

namespace {

/**
 * @brief 构建全局 QSS
 *
 * 结构按「容器 → 文本 → 控件」分层，与 Qt 官方的层叠顺序一致：
 * 同等特异性下后写的规则覆盖先写的，因此交互态（`:hover` / `:pressed`）
 * 必须写在基础规则之后。
 *
 * 字体统一用 sans-serif + 明确字号：eglfs 直出时没有桌面环境的字体配置，
 * 不指定就会落到难以预测的默认值上。
 */
QString build_stylesheet() {
    return QStringLiteral(R"(
/* ---------- 全局基底 ---------- */
QWidget {
    font-family: "Noto Sans CJK SC", "Source Han Sans SC", "WenQuanYi Micro Hei", sans-serif;
    font-size: 10pt;
    color: %1;
}

QMainWindow, QDialog {
    background-color: %2;
}

/* ---------- 分组卡片 ---------- */
QGroupBox {
    background-color: %3;
    border: 1px solid %4;
    border-radius: 6px;
    margin-top: 16px;
    padding: 10px 10px 8px 10px;
    font-weight: bold;
    color: %5;
}

/* 标题压在边框上，背景要与卡片同色才能「切开」边框 */
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    left: 12px;
    padding: 0 6px;
    background-color: %3;
    color: %5;
}

/* ---------- 文本 ---------- */
QLabel {
    background: transparent;
}

/* 状态文本用等宽字体：GOOD / DEGRADED / BAD 长度不同，
   等宽能让左对齐的列看起来整齐 */
QLabel#state_text {
    font-family: "DejaVu Sans Mono", "Noto Sans Mono", monospace;
    font-size: 9pt;
}

/* 整体分数：最重要的一个数字，给足视觉权重 */
QLabel#score_value {
    font-size: 26pt;
    font-weight: bold;
}

/* 网卡名：等宽 + 加粗，避免 wlan0 / wlan1 混淆 */
QLabel#iface_name {
    font-family: "DejaVu Sans Mono", "Noto Sans Mono", monospace;
    font-size: 12pt;
    font-weight: bold;
}

/* 元信息（档位、时间戳）：弱化但不至于看不见 */
QLabel#meta_info {
    color: %6;
    font-size: 9pt;
}

/* 底栏的经验 / 诊断文本 */
QLabel#detail_text {
    color: %6;
    font-size: 9pt;
}

/* ---------- 按钮 ---------- */
QPushButton {
    background-color: %3;
    border: 1px solid %4;
    border-radius: 4px;
    padding: 5px 16px;
    color: %5;
}

QPushButton:hover {
    background-color: #EEF1F6;
    border-color: #C5CAD3;
}

QPushButton:pressed {
    background-color: #E2E6ED;
}

QPushButton:disabled {
    color: %7;
    background-color: #F0F1F3;
    border-color: %4;
}

/* ---------- 分隔器 ---------- */
QSplitter::handle {
    background-color: %2;
}

QSplitter::handle:horizontal {
    width: 8px;
}

/* ---------- 状态栏 ---------- */
QStatusBar {
    background-color: %3;
    border-top: 1px solid %4;
    color: %6;
    font-size: 9pt;
}

QStatusBar::item {
    border: none;
}

/* ---------- 提示气泡 ---------- */
QToolTip {
    background-color: #37474F;
    color: #FFFFFF;
    border: 1px solid #37474F;
    padding: 4px 6px;
}
)")
        .arg(QString::fromLatin1(ThemeColors::kTextPrimary))   // %1
        .arg(QString::fromLatin1(ThemeColors::kBackground))    // %2
        .arg(QString::fromLatin1(ThemeColors::kSurface))       // %3
        .arg(QString::fromLatin1(ThemeColors::kDivider))       // %4
        .arg(QString::fromLatin1(ThemeColors::kTextPrimary))   // %5
        .arg(QString::fromLatin1(ThemeColors::kTextSecondary)) // %6
        .arg(QString::fromLatin1(ThemeColors::kUnknown));      // %7
}

/**
 * @brief 构建调色板
 *
 * QSS 覆盖不到的地方（原生对话框、某些子控件、QToolTip 之外的 popup）
 * 仍读 palette，因此两者要一致，否则会出现浅色界面上蹦出一块深色区域。
 *
 * 这里刻意保持**浅色**主题：看板多在室内/机柜旁使用，浅色在强光下可读性更好；
 * 深色更适合长时间盯屏。若将来要加深色，改这一处 + QSS 即可。
 */
QPalette build_palette() {
    QPalette p;
    p.setColor(QPalette::Window, QColor(ThemeColors::kBackground));
    p.setColor(QPalette::WindowText, QColor(ThemeColors::kTextPrimary));
    p.setColor(QPalette::Base, QColor(ThemeColors::kSurface));
    p.setColor(QPalette::AlternateBase, QColor(ThemeColors::kBackground));
    p.setColor(QPalette::Text, QColor(ThemeColors::kTextPrimary));
    p.setColor(QPalette::Button, QColor(ThemeColors::kSurface));
    p.setColor(QPalette::ButtonText, QColor(ThemeColors::kTextPrimary));
    p.setColor(QPalette::Highlight, QColor(0x1A, 0x73, 0xE8));
    p.setColor(QPalette::HighlightedText, QColor(Qt::white));
    p.setColor(QPalette::ToolTipBase, QColor(0x37, 0x47, 0x4F));
    p.setColor(QPalette::ToolTipText, QColor(Qt::white));
    p.setColor(QPalette::Disabled, QPalette::Text, QColor(ThemeColors::kUnknown));
    p.setColor(QPalette::Disabled, QPalette::ButtonText,
               QColor(ThemeColors::kUnknown));
    return p;
}

} // namespace

QString apply_theme() {
    QString style_name = QStringLiteral("Fusion");
    if (QStyle* fusion = QStyleFactory::create(style_name)) {
        QApplication::setStyle(fusion);
    } else {
        // 极端情况下 Fusion 不可用（静态构建裁剪掉），沿用当前样式但不中断，
        // 因为 QSS 仍会生效——只是某些控件细节会跟着平台样式走。
        style_name = QStringLiteral("(platform default)");
    }

    qApp->setPalette(build_palette());
    qApp->setStyleSheet(build_stylesheet());
    return style_name;
}

} // namespace dashboard
} // namespace weaknet

/**
 * @file theme.hpp
 * @brief 看板视觉主题（配色、字号、QSS）
 *
 * ## 为什么需要单独的 theme
 *
 * 改进前的界面没有全局样式表，8 处 `setStyleSheet` 全是零散写颜色。
 * 这带来三个具体后果：
 *
 * 1. **配色散落**：状态色 `#2E7D32` / `#F9A825` / `#C62828` 在
 *    `main_window.cpp` 里出现 3 次（`state_color`、`summary_label_` 的 html、
 *    折线图默认色），改一处漏两处；
 * 2. **无主题层**：想换深色/浅色必须逐处改代码；
 * 3. **布局靠默认值**：`QGroupBox` 用系统默认边框，`QPushButton` 是系统
 *    原生样式，在 eglfs 直出时显得像未完成的调试界面。
 *
 * ## 与部件级 setStyleSheet 的关系（已实测）
 *
 * 本主题用 `qApp->setStyleSheet()` 设置全局规则，部件级
 * `setStyleSheet("color: ...")` 仍然生效且**不会重置**全局字号——
 * 实测两者笔画高度都是 22px（`/tmp/qsstest/t4.cpp`）。
 *
 * 因此 `MainWindow::update_status_label()` 里那套运行时按状态改色的逻辑
 * 可以原样保留，本文件只负责提供全局外观基线。
 *
 * ## 配色依据
 *
 * 状态色取自 `server/include/assurance/health_state.hpp:15-23` 的四个枚举，
 * 色值选的是 Material Design 的 700/800 色阶：在浅色背景上对比度足够
 * （GOOD `#2E7D32` 对白底的对比度约 5.1:1，满足 WCAG AA 的 4.5:1）。
 */

#ifndef WEAKNET_QT_DASHBOARD_THEME_HPP
#define WEAKNET_QT_DASHBOARD_THEME_HPP

#include <QString>

namespace weaknet {
namespace dashboard {

/**
 * @brief 语义色板
 *
 * 集中管理，避免同一个状态色在多个文件里各写一遍。
 * `LineChartWidget` 与 `MainWindow` 都从这里取。
 */
struct ThemeColors {
    /// GOOD —— Material Green 800
    static constexpr const char* kGood = "#2E7D32";
    /// DEGRADED —— Material Amber 800
    static constexpr const char* kDegraded = "#F9A825";
    /// BAD —— Material Red 800
    static constexpr const char* kBad = "#C62828";
    /// UNKNOWN / 不适用 —— Material Grey 500
    static constexpr const char* kUnknown = "#9E9E9E";

    /// 主文字色
    static constexpr const char* kTextPrimary = "#212121";
    /// 次要文字色（提示、元信息）
    static constexpr const char* kTextSecondary = "#616161";
    /// 更弱的文字色（轴标签、占位）
    static constexpr const char* kTextMuted = "#9E9E9E";

    /// 页面底色
    static constexpr const char* kBackground = "#F5F6F8";
    /// 卡片 / 分组底色
    static constexpr const char* kSurface = "#FFFFFF";
    /// 分隔线
    static constexpr const char* kDivider = "#E0E3E8";
    /// 网格线
    static constexpr const char* kGrid = "#E8EBF0";
};

/**
 * @brief 应用全局样式表
 *
 * 必须在 `QApplication` 构造之后、`MainWindow` 构造之前调用。
 *
 * 用 `QStyleFactory::create("Fusion")` 做基底：eglfs/offscreen 下原生样式
 * 会退化得很难看，Fusion 是跨平台一致的，也是 Qt 官方推荐的 QSS 基底。
 *
 * @return 实际生效的样式名，便于日志确认
 */
QString apply_theme();

} // namespace dashboard
} // namespace weaknet

#endif // WEAKNET_QT_DASHBOARD_THEME_HPP

