121	        const double ratio = static_cast<double>(i) / kGridLines;
122	        const int y = plot.bottom() - static_cast<int>(ratio * plot.height());
123	
124	        painter->setPen(QPen(QColor(0xE0, 0xE0, 0xE0), 1, Qt::SolidLine));
125	        painter->drawLine(plot.left(), y, plot.right(), y);
