131	                          QString::number(value, 'f', 0));
132	    }
133	
134	    // --- 数据为空时的提示 ---
135	    if (scores_.isEmpty()) {
136	        painter->setPen(QColor(0x99, 0x99, 0x99));
137	        painter->drawText(plot, Qt::AlignCenter, QStringLiteral("暂无历史数据"));
