    font-size: 10pt;
    color: %1;
}

QMainWindow, QDialog {
    background-color: %2;
}

/* ---------- 分组卡片 ---------- */
QGroupBox {
    background-color: %3;
    border: 1px solid %4;
    border-radius: 6px;
    margin-top: 14px;
    padding: 6px 10px 4px 10px;
    font-weight: bold;
    color: %5;
}

/* 标题压在边框上，背景要与卡片同色才能「切开」边框 */
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    left: 12px;
    padding: 0 6px;
    background-color: %3;
    color: %5;
}

/* ---------- 文本 ---------- */
QLabel {
    background: transparent;
}

/* 状态文本用等宽字体：GOOD / DEGRADED / BAD 长度不同，
   等宽能让左对齐的列看起来整齐 */
QLabel#state_text {
    font-family: "DejaVu Sans Mono", "Noto Sans Mono", monospace;
    font-size: 9pt;
}

/* 整体分数：最重要的一个数字，给足视觉权重 */
QLabel#score_value {
    font-size: 26pt;
    font-weight: bold;
}

/* 网卡名：等宽 + 加粗，避免 wlan0 / wlan1 混淆 */
QLabel#iface_name {
    font-family: "DejaVu Sans Mono", "Noto Sans Mono", monospace;
    font-size: 12pt;
    font-weight: bold;
}

/* 元信息（档位、时间戳）：弱化但不至于看不见 */
QLabel#meta_info {
    color: %6;
    font-size: 9pt;
}

/* 底栏的经验 / 诊断文本 */
QLabel#detail_text {
    color: %6;
    font-size: 9pt;
}

/* 底栏结论行：比明细更重要，用主文字色而非弱化色 */
QLabel#primary_text {
    color: %5;
    font-size: 10pt;
}

/* 服务端主动标记的警告：红色是语义不是装饰，与 BAD 状态同色系 */
QLabel#warn_text {
    color: %8;
    font-size: 10pt;
}

/* ---------- 按钮 ---------- */
QPushButton {
    background-color: %3;
    border: 1px solid %4;
    border-radius: 4px;
    padding: 5px 16px;
    color: %5;
}

QPushButton:hover {
    background-color: #EEF1F6;
    border-color: #C5CAD3;
}

QPushButton:pressed {
    background-color: #E2E6ED;
}

QPushButton:disabled {
    color: %7;
    background-color: #F0F1F3;
    border-color: %4;
}

/* ---------- 分隔器 ---------- */
QSplitter::handle {
    background-color: %2;
}

QSplitter::handle:horizontal {
    width: 8px;
}

/* ---------- 状态栏 ---------- */
QStatusBar {
    background-color: %3;
    border-top: 1px solid %4;
    color: %6;
    font-size: 9pt;
}

QStatusBar::item {
    border: none;
}

/* ---------- 提示气泡 ---------- */
QToolTip {
    background-color: #37474F;
    color: #FFFFFF;
    border: 1px solid #37474F;
    padding: 4px 6px;
}
