    const QRect left_column(0, 0, img.width() / 3, img.height());
    const int left_good =
        count_exact_below(img, left_column, theme_qcolor(ThemeColors::kGood));

    // 8 个 GOOD 维度 × （圆点 + 状态词）都要着色。
