41	/**
42	 * @brief 创建一行「名称 + 状态点 + 状态文本」
43	 *
44	 * @param name        维度中文名
45	 * @param state_label 输出：状态标签控件
46	 * @param dot_label   输出：状态圆点控件（跟随状态着色）
47	 * @return 该行的布局
48	 *
49	 * 布局用固定列宽而非 stretch：14 行对齐后能当表格读，
50	 * 不会因为某个维度名长一点就把状态列推歪。
51	 */
52	QWidget* make_status_row(const QString& name, QLabel** state_label,
53	                         QLabel** dot_label) {
54	    auto* row = new QWidget;
55	    auto* layout = new QHBoxLayout(row);
56	    layout->setContentsMargins(2, 2, 2, 2);
57	    layout->setSpacing(8);
58	
59	    auto* name_label = new QLabel(name);
60	    name_label->setMinimumWidth(84);
61	    name_label->setObjectName(QStringLiteral("dim_name"));
62	
63	    auto* dot = new QLabel(QStringLiteral("●"));
64	    dot->setObjectName(QStringLiteral("state_dot"));
65	    dot->setFixedWidth(14);
66	    dot->setAlignment(Qt::AlignCenter);
67	
68	    auto* state = new QLabel(QStringLiteral("--"));
69	    state->setObjectName(QStringLiteral("state_text"));
70	
71	    layout->addWidget(name_label);
72	    layout->addWidget(dot);
73	    layout->addWidget(state);
74	    layout->addStretch();
75	
76	    *state_label = state;
77	    *dot_label = dot;
78	    return row;
79	}
